<?php
require_once __DIR__ . '/../../cors.php';require_once __DIR__ . '/../../db/db.php';require_once __DIR__ . '/../../reusables/organization_guard.php';header('Content-Type: application/json');$ctx=requireOrganizationAccess($pdo,'org_settings.org_documents.read');
try{$s=$pdo->prepare("SELECT d.id,d.doc_type,d.original_name,d.mime_type,d.file_size,d.status,d.rejection_reason,d.reviewed_at,d.created_at,CONCAT_WS(' ',u.first_name,u.last_name) reviewer_name FROM organization_documents d LEFT JOIN users u ON u.id=d.reviewed_by WHERE d.organization_id=? ORDER BY d.created_at DESC");$s->execute([$ctx['organization_id']]);$docs=$s->fetchAll(PDO::FETCH_ASSOC);$fleet=$pdo->prepare("SELECT id,unit_code,plate_number,registration_expiry,inspection_expiry,status FROM ambulances WHERE organization_id=? AND deleted_at IS NULL ORDER BY unit_code");$fleet->execute([$ctx['organization_id']]);$units=$fleet->fetchAll(PDO::FETCH_ASSOC);$stats=['documents'=>count($docs),'approved'=>count(array_filter($docs,fn($x)=>$x['status']==='approved')),'pending'=>count(array_filter($docs,fn($x)=>$x['status']==='pending')),'credential_alerts'=>0];$today=date('Y-m-d');$warn=date('Y-m-d',strtotime('+30 days'));foreach($units as &$u){$alerts=[];foreach(['registration_expiry'=>'Registration','inspection_expiry'=>'Inspection'] as $k=>$label){if(!empty($u[$k])&&$u[$k]<=$warn)$alerts[]=['label'=>$label,'date'=>$u[$k],'expired'=>$u[$k]<$today];}$u['credential_alerts']=$alerts;$stats['credential_alerts']+=count($alerts);}unset($u);echo json_encode(['success'=>true,'documents'=>$docs,'fleet_credentials'=>$units,'stats'=>$stats]);}catch(Throwable $e){error_log('Org docs failed: '.$e->getMessage());organizationJsonError(500,'Unable to load organization documents.');}
